SELECT A.ASESS_RCORD_YMD AS ASESS_RCORD_YMD, /* 사정기록일자 */ A.EXPERT_OPIN_CN AS EXPERT_OPIN_CN, /* 전문가소견내용 */ A.INNER_OPIN_CN AS INNER_OPIN_CN, /* 내부소견내용 */ A.DGDGR_SE_CD AS DGDGR_SE_CD, /* 위험도구분코드 */ A.BDY_TROBL_CN AS BDY_TROBL_CN, /* 신체장애내용 */
A.LRN_CN AS LRN_CN, /* 학습내용 */ A.EMTNL_SPFE_CN AS EMTNL_SPFE_CN, /* 정서적특징내용 */ A.TWDPSN_REL_CN AS TWDPSN_REL_CN, /* 대인관계내용 */ A.CHIL_CNFRNT_PROBM_CN AS CHIL_CNFRNT_PROBM_CN, /* 아동당면문제내용 */ A.CHIL_STGTH_CN AS CHIL_STGTH_CN, /* 아동강점내용 */
A.FAM_CNFRNT_TASK_CN AS FAM_CNFRNT_TASK_CN, /* 가족당면과제내용 */ A.FAM_STGTH_CN AS FAM_STGTH_CN, /* 가족강점내용 */ A.INST_NO AS INST_NO, /* 기관번호 */ A.PIC_NO AS PIC_NO, /* 담당자번호 */
A.CASE_MNG_NO AS CASE_MNG_NO, /* 사례관리번호 */ A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ FROM AEA120 A /* 사정기록지 */ WHERE A.CASE_MNG_NO = #{CASE_MNG_NO} AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

/* selectSprtPensnById - Lee MS */
SELECT A.RCMDTN_INST_NO AS RCMDTN_INST_NO, /* 추천기관번호 */ B.INST_NM AS RCMDTN_INST_NM, /* 추천기관명 */ A.CTPV_SE_CD AS CTPV_SE_CD, /* 시도구분코드 */ A.SGG_CD AS SGG_CD, /* 시군구코드 */ C.CTPV_NM || ' ' || C.SGG_NM AS SGG_NM, /* 시군구명 */
A.SLFRL_SPRT_PENSN_SE_CD AS SLFRL_SPRT_PENSN_SE_CD, /* 자립지원수당구분코드 */ A.DCSN_YMD AS DCSN_YMD, /* 결정일자 */ A.PENSN_GIVE_YM AS PENSN_GIVE_YM, /* 수당지급연월 */ A.SALARY_AMT AS SALARY_AMT, /* 급여금액 */
A.SLFRL_SPRT_CS_SE_CD AS SLFRL_SPRT_CS_SE_CD, /* 자립지원사유구분코드 */ A.SLFRL_SPRT_CS_ETC_CN AS SLFRL_SPRT_CS_ETC_CN, /* 자립지원사유기타내용 */
A.CASE_MNG_NO AS CASE_MNG_NO, /* 사례관리번호 */ A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO, /* 사례관리차수 */ A.MNG_SN AS MNG_SN /* 관리일련번호 */ FROM AEA140 A, SAA000 B, SAA020 C /* 자립지원수당 */ WHERE A.RCMDTN_INST_NO = B.INST_NO AND A.SGG_CD = C.SGG_CD(+) AND A.CASE_MNG_NO = #{CASE_MNG_NO} AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

