SELECT A.RTHOUS_SPRT_SE_CD AS RTHOUS_SPRT_SE_CD, /* 임대주택지원구분코드 */ A.CTRT_YMD AS CTRT_YMD, /* 계약일자 */ A.CTRT_BGNG_YMD AS CTRT_BGNG_YMD, /* 계약시작일자 */ A.CTRT_END_YMD AS CTRT_END_YMD, /* 계약종료일자 */ A.RTHOUS_PRCHS_SE_CD AS RTHOUS_PRCHS_SE_CD, /* 임대주택구매구분코드 */
A.RENT_PST_ADDR AS RENT_PST_ADDR, /* 임대우편주소 */ A.RENT_ADDR AS RENT_ADDR, /* 임대주소 */ A.CTRT_MDSTRM_END_YMD AS CTRT_MDSTRM_END_YMD, /* 계약중도종료일자 */ A.CTRT_MDSTRM_END_CN AS CTRT_MDSTRM_END_CN, /* 계약중도종료내용 */
A.CASE_MNG_NO AS CASE_MNG_NO, /* 사례관리번호 */ A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO, /* 사례관리차수 */ A.MNG_SN AS MNG_SN /* 관리일련번호 */
